{"source":{"files":[{"name":"firestore.rules","content":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_json_2pow53_plus1/{doc} {
      allow get: if resource.data.g == 9007199254740993;
    }
    match /c_json_huge_number/{doc} {
      allow get: if resource.data.g is float;
    }
    match /c_resource_id/{doc} {
      allow get: if resource.id == 'doc';
    }
    match /c_resource_name_absent/{doc} {
      allow get: if resource.__name__ == null || true;
    }
    match /c_request_resource_absent_on_get/{doc} {
      allow get: if request.resource == null;
    }
    match /c_auth_token_nested/{doc} {
      allow get: if request.auth.token.firebase.sign_in_provider == 'password';
    }
    match /c_auth_token_bool/{doc} {
      allow get: if request.auth.token.admin == true;
    }
    match /c_auth_token_missing_claim/{doc} {
      allow get: if request.auth.token.missing == true;
    }
    match /c_auth_without_token_size/{doc} {
      allow get: if request.auth.token.size() == 0;
    }
  }
}
